const enriches = {
    "aether": {
        src: "data:image/png;base64,",
        type: "image",
        style: {height: "1em", verticalAlign: "middle"}
    },
    "aether-white": {
        src: "data:image/png;base64,",
        style: { height: "1em", verticalAlign: "middle" },
        type: "image"
    },
    "newline": {
        type: "newline"
    },
    "bold": {
        style: {fontWeight: 'bold'}
    },
    "italic": {
        style: {fontStyle: 'italic'}
    },
    "color": {
        callStyle: (color) => ({color: `${color}`})
    },
    "list-item": {}
}

const getHTML = (enrich, key) => {
    switch(enrich.type) {
        case "image":
            return (
                <img src={enrich.src ?? ''} key={key} alt={enrich?.alt ?? ''} style={enrich.style ?? {}} />
            )
        case "newline":
            return (
                <br />
            )
        case "text":
            return (
                <span style={{display: 'inline', ...(enrich.styles ?? {})}}>{enrich.text}</span>
            )
        case "list-item":
            return (
                <ul style={{margin: '0'}}>
                    <li style={{listStyleType: 'circle'}}>{enrich?.text ?? ''}</li>
                </ul>
            )
        default:
            return (
                <span>Error: unknown enrich type: {enrich.type}</span>
            )
    }
}

const parseColor = (colorModifier) => {
    const parts = colorModifier.split(":")
    if (parts.length < 2) {
        return 'black'
    }
    return parts[1]
}

export default function enrichText (text) {
  const parts = text.split(/\$\{(.*?)\}/g);

  return parts.map((part, index) => {
    if (enriches[part]) {
      return getHTML(enriches[part])
    }

    if (part.includes('list-item')) {
        const p = part.split('|')
        if (p.length < 2) {
            return part
        }
        return getHTML({
            type: 'list-item',
            text: p[0]
        })
    }

    const textWithModifiers = part.split('|')
    if (textWithModifiers.length < 2) {
        return part;
    }
    const text = textWithModifiers.shift()
    const styles = textWithModifiers.reduce((acc, curr) => {
        if (curr.includes('color:')) {
            const color = parseColor(curr)
            return {
                ...acc,
                ...enriches['color'].callStyle(color)
            }
        }
        if (enriches[curr]) {
            return {
                ...acc,
                ...(enriches[curr]?.style ?? {}) 
            }
        }
        return acc
    }, {})

    return getHTML({
        "type": "text",
        text,
        styles
    }, index)
  });
};